<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;
Auth::requirePermission('competitors.view');$pdo=Database::connection();
$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$status=(string)($_GET['status']??'');$sort=(string)($_GET['sort']??'name');$order=strtolower((string)($_GET['order']??'asc'))==='desc'?'DESC':'ASC';$perPage=in_array((int)($_GET['per_page']??50),[25,50,100,200,500],true)?(int)$_GET['per_page']:50;$page=max(1,(int)($_GET['page']??1));
$where=['1=1'];$params=[];if($q!==''){$where[]='(LOWER(w.display_name) LIKE LOWER(:name) OR LOWER(w.identity_code) LIKE LOWER(:code) OR LOWER(w.country) LIKE LOWER(:country))';$like='%'.$q.'%';$params+=['name'=>$like,'code'=>$like,'country'=>$like];}if(in_array($type,['solo','couple','duo','pro_am','team'],true)){$where[]='w.entry_type=:type';$params['type']=$type;}if(in_array($status,['active','archived'],true)){$where[]='w.status=:status';$params['status']=$status;}$whereSql=implode(' AND ',$where);
$sortMap=['name'=>'w.display_name','wdc_id'=>'w.identity_code','type'=>'w.entry_type','country'=>'w.country','points'=>'championship_points','entries'=>'published_entries','status'=>'w.status','updated'=>'w.updated_at'];$orderBy=$sortMap[$sort]??$sortMap['name'];$sort=array_key_exists($sort,$sortMap)?$sort:'name';
$base="SELECT w.*,COALESCE(p.championship_points,0) championship_points,COALESCE(p.published_entries,0) published_entries,COALESCE(reg.registration_count,0) registration_count,reg.registered_categories,c.photo_url solo_photo,c.country solo_country,c.id solo_profile_id FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id LEFT JOIN(SELECT wdc_identity_id,SUM(points) championship_points,COUNT(*) published_entries FROM bdc_wdc_championship_points GROUP BY wdc_identity_id)p ON p.wdc_identity_id=w.id LEFT JOIN(SELECT wdc_identity_id,COUNT(*) registration_count,GROUP_CONCAT(DISTINCT category_name ORDER BY category_name SEPARATOR ', ') registered_categories FROM bdc_wdc_registrations WHERE status='registered' GROUP BY wdc_identity_id)reg ON reg.wdc_identity_id=w.id WHERE {$whereSql}";
if(($_GET['export']??'')==='csv'){Auth::requireSuperAdmin();$s=$pdo->prepare($base." ORDER BY {$orderBy} {$order},w.id");$s->execute($params);header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="wdc-competitors-'.date('Y-m-d-His').'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['WDC ID','Name','Entry Type','Country','Registered Categories','Registration Count','Championship Points','Published Entries','Status']);foreach($s->fetchAll() as $r)fputcsv($out,[$r['identity_code'],$r['display_name'],$r['entry_type'],$r['country']?:$r['solo_country'],$r['registered_categories'],$r['registration_count'],$r['championship_points'],$r['published_entries'],$r['status']]);fclose($out);exit;}
$count=$pdo->prepare("SELECT COUNT(*) FROM bdc_wdc_identities w WHERE {$whereSql}");$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$stmt=$pdo->prepare($base." ORDER BY {$orderBy} {$order},w.id LIMIT :limit OFFSET :offset");foreach($params as $k=>$v)$stmt->bindValue(':'.$k,$v);$stmt->bindValue(':limit',$perPage,PDO::PARAM_INT);$stmt->bindValue(':offset',$offset,PDO::PARAM_INT);$stmt->execute();$rows=$stmt->fetchAll();
$counts=['all'=>(int)$pdo->query('SELECT COUNT(*) FROM bdc_wdc_identities')->fetchColumn(),'registrations'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_registrations WHERE status='registered'")->fetchColumn(),'solo'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_identities WHERE entry_type='solo'")->fetchColumn(),'couple_duo'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_identities WHERE entry_type IN('couple','duo','pro_am')")->fetchColumn(),'team'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_identities WHERE entry_type='team'")->fetchColumn(),'missing_photo'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id WHERE COALESCE(w.photo_url,c.photo_url,'')=''")->fetchColumn()];
function dcq(array $changes=[]):string{$q=array_merge($_GET,$changes);foreach($q as $k=>$v)if($v===''||$v===null)unset($q[$k]);return'?'.http_build_query($q);}function dcsort(string $column,string $current,string $order):string{return dcq(['sort'=>$column,'order'=>$current===$column&&$order==='ASC'?'desc':'asc','page'=>1]);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Competitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem}.photo{width:48px;height:48px;object-fit:cover;border-radius:8px}.sortable{color:inherit;text-decoration:none}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="<?=e(url('admin/'))?>">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="<?=e(url('admin/dance-cup/'))?>">Dance Cup</a></div></nav><main class="container-fluid py-4"><div class="d-flex justify-content-between gap-3 flex-wrap mb-3"><div><h1 class="h3 mb-1">Dance Cup Competitor</h1><p class="text-muted mb-0">Permanent WDC solo, couple, duo and team identities.</p></div><div class="d-flex gap-2"><?php if(Auth::isSuperAdmin()):?><a class="btn btn-outline-success" href="<?=e(dcq(['export'=>'csv','page'=>null]))?>">Export Competitors CSV</a><?php endif;?><?php if(Auth::can('competitors.edit')):?><a class="btn btn-dark" href="competitor-edit.php">Add competitor</a><?php endif;?></div></div><section class="summary mb-4"><?php foreach($counts as $key=>$value):?><div class="card border-0 shadow-sm"><div class="card-body"><div class="small text-muted"><?=e(ucwords(str_replace('_',' ',$key)))?></div><strong class="fs-2"><?=$value?></strong></div></div><?php endforeach;?></section><form class="card border-0 shadow-sm mb-3"><div class="card-body row g-2"><div class="col-lg-5"><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, WDC ID or country"></div><div class="col-lg-2"><label class="form-label">Entry type</label><select class="form-select" name="type"><option value="">All types</option><?php foreach(['solo','couple','duo','pro_am','team'] as $v):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">All statuses</option><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="archived" <?=$status==='archived'?'selected':''?>>Archived</option></select></div><div class="col-lg-2"><label class="form-label">Rows</label><select class="form-select" name="per_page"><?php foreach([25,50,100,200,500] as $v):?><option <?=$perPage===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-lg-1 d-flex align-items-end"><button class="btn btn-dark w-100">Apply</button></div></div></form><div class="small text-muted mb-2">Showing <?=$total?($offset+1):0?> to <?=min($offset+$perPage,$total)?> of <?=$total?> competitors</div><section class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Photo</th><th><a class="sortable" href="<?=e(dcsort('wdc_id',$sort,$order))?>">WDC ID</a></th><th><a class="sortable" href="<?=e(dcsort('name',$sort,$order))?>">Name</a></th><th>Type</th><th>Country</th><th>Championship Points</th><th>Published Entries</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$photo=$r['photo_url']?:$r['solo_photo']?:url('public/assets/img/default-competitor.svg');?><tr id="wdc-<?=(int)$r['id']?>"><td><img class="photo" src="<?=e($photo)?>" alt=""></td><td><code><?=e($r['identity_code'])?></code></td><td><strong><?=e($r['display_name'])?></strong></td><td><?=e(ucwords(str_replace('_',' ',$r['entry_type'])))?></td><td><?=e($r['country']?:$r['solo_country']?:'—')?></td><td><strong><?=e((string)(float)$r['championship_points'])?></strong></td><td><?=(int)$r['published_entries']?></td><td><span class="badge text-bg-<?=$r['status']==='active'?'success':'secondary'?>"><?=e(ucfirst($r['status']))?></span></td><td class="text-end"><?php if(Auth::can('competitors.edit')):?><a class="btn btn-sm btn-outline-dark" href="competitor-edit.php?id=<?=(int)$r['id']?>">Edit</a><?php if($r['solo_profile_id']):?><a class="btn btn-sm btn-outline-primary" href="<?=e(url('admin/competitors/photo-adjust.php?id='.(int)$r['solo_profile_id']))?>">Adjust photo</a><?php endif;?><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9" class="text-center text-muted py-5">No Dance Cup competitors match the selected filters.</td></tr><?php endif;?></tbody></table></div></section><?php if($pages>1):?><nav class="mt-3"><ul class="pagination"><?php for($i=1;$i<=$pages;$i++):?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="<?=e(dcq(['page'=>$i]))?>"><?=$i?></a></li><?php endfor;?></ul></nav><?php endif;?></main></body></html>
